% ========== 第一条（基本原則） ==========
% 条文要旨: 私権は、公共の福祉に適合しなければならない。 ２ 権利の行使及び義務の履行は、信義に従い誠実に行わなければならない。 ３ 権利の濫用は、これを許さない。
