% ========== 第三条 ==========
% 条文要旨: 私権の享有は、出生に始まる。 ２ 外国人は、法令又は条約の規定により禁止される場合を除き、私権を享有する。
% TODO: 要件事実論に基づきルールを記述

% ========== 第三条の二 ==========
% 条文要旨: 法律行為の当事者が意思表示をした時に意思能力を有しなかったときは、その法律行為は、無効とする。
% 意思能力を欠く法律行為は無効
法律行為の無効(_行為) <=
    意思表示_f(_行為者, _行為),
    意思能力なし_f(_行為者, _行為).

% ========== 第四条（成年） ==========
% 条文要旨: 年齢十八歳をもって、成年とする。
% 十八歳をもって成年とする（定義的事実）
成年_f(_者) <=
    年齢十八歳以上_f(_者).

% ========== 第五条（未成年者の法律行為） ==========
% 条文要旨: 未成年者が法律行為をするには、その法定代理人の同意を得なければならない。ただし、単に権利を得、又は義務を免れる法律行為については、この限りでない。 ２ 前項の規定に反する法律行為は、取り消すことができる。 ３ 第一項の規定にかかわらず、法…
% 第5条第2項: 同意なき未成年者の法律行為は取り消すことができる
取消可能(_行為) <=
    未成年者_f(_行為者),
    法律行為_f(_行為者, _行為),
    法定代理人の同意なし_f(_行為).

% 第5条第1項ただし書
exception(取消可能(_行為), 単に権利を得又は義務を免れる行為_f(_行為)).

% 第5条第3項
exception(取消可能(_行為), 許可された処分_f(_行為)).

% ========== 第六条（未成年者の営業の許可） ==========
% 条文要旨: 一種又は数種の営業を許された未成年者は、その営業に関しては、成年者と同一の行為能力を有する。 ２ 前項の場合において、未成年者がその営業に堪えることができない事由があるときは、その法定代理人は、第四編（親族）の規定に従い、その許可を取り消…
% 営業を許された未成年者は、その営業に関し成年者と同一の行為能力
成年者と同一の行為能力(_行為者, _営業) <=
    未成年者_f(_行為者),
    営業の許可_f(_行為者, _営業).

