    催告_f(_相手方, _行為),
    確答なし_f(_行為),
    追認擬制の類型_f(_行為).

取消したものとみなす(_行為) <=
    制限行為能力者の相手方_f(_相手方),
    催告_f(_相手方, _行為),
    確答なし_f(_行為),
    取消擬制の類型_f(_行為).

