% ========== 第九十一条（任意規定と異なる意思表示） ==========
% 条文要旨: 法律行為の当事者が法令中の公の秩序に関しない規定と異なる意思を表示したときは、その意思に従う。
% TODO: 要件事実論に基づきルールを記述

% ========== 第九十二条（任意規定と異なる慣習） ==========
% 条文要旨: 法令中の公の秩序に関しない規定と異なる慣習がある場合において、法律行為の当事者がその慣習による意思を有しているものと認められるときは、その慣習に従う。
% TODO: 要件事実論に基づきルールを記述

% ========== 第九十三条（心<ruby>裡<rt>り</rt></ruby>留保） ==========
% 条文要旨: 意思表示は、表意者がその真意ではないことを知ってしたときであっても、そのためにその効力を妨げられない。ただし、相手方がその意思表示が表意者の真意ではないことを知り、又は知ることができたときは、その意思表示は、無効とする。 ２ 前項ただし書…
% 心裏留保: 原則として意思表示は有効。相手方が悪意または有過失なら無効
意思表示の無効(_意思表示) <=
    心裏留保_f(_表意者, _意思表示),
    相手方の悪意又は有過失_f(_相手方, _意思表示).

% ========== 第九十四条（虚偽表示） ==========
% 条文要旨: 相手方と通じてした虚偽の意思表示は、無効とする。 ２ 前項の規定による意思表示の無効は、善意の第三者に対抗することができない。
% 虚偽表示は無効
意思表示の無効(_意思表示) <=
    通謀虚偽表示_f(_表意者, _相手方, _意思表示).

% ただし善意の第三者に対抗不可
exception(意思表示の無効(_意思表示), 善意の第三者_f(_第三者, _意思表示)).

% ========== 第九十五条（錯誤） ==========
% 条文要旨: 意思表示は、次に掲げる錯誤に基づくものであって、その錯誤が法律行為の目的及び取引上の社会通念に照らして重要なものであるときは、取り消すことができる。 - 一 意思表示に対応する意思を欠く錯誤 - 二 表意者が法律行為の基礎とした事情につい…
% 錯誤による取消し（第95条第1項）
取消可能(_意思表示) <=
    意思表示_f(_表意者, _意思表示),
    錯誤_f(_表意者, _意思表示),
    錯誤が重要_f(_意思表示).

% 第95条第3項: 重大な過失があるときは原則取消不可
exception(取消可能(_意思表示), 表意者の重大な過失_f(_表意者, _意思表示)).

% 第95条第3項ただし書の再抗弁は個別類型として事実で与える
exception(表意者の重大な過失_f(_表意者, _意思表示), 重大な過失でも取消しうる類型_f(_意思表示)).

% ========== 第九十六条（詐欺又は強迫） ==========
% 条文要旨: 詐欺又は強迫による意思表示は、取り消すことができる。 ２ 相手方に対する意思表示について第三者が詐欺を行った場合においては、相手方がその事実を知り、又は知ることができたときに限り、その意思表示を取り消すことができる。 ３ 前二項の規定によ…
% 詐欺または強迫による意思表示は取り消すことができる
取消可能(_意思表示) <=
    意思表示_f(_表意者, _意思表示),
    詐欺_f(_相手方, _表意者, _意思表示).

取消可能(_意思表示) <=
    意思表示_f(_表意者, _意思表示),
    強迫_f(_相手方, _表意者, _意思表示).

% 第96条第3項: 詐欺取消しは善意かつ無過失の第三者に対抗不可
exception(取消可能(_意思表示), 詐欺取消しと善意無過失の第三者_f(_第三者, _意思表示)).

% ========== 第九十七条（意思表示の効力発生時期等） ==========
% 条文要旨: 意思表示は、その通知が相手方に到達した時からその効力を生ずる。 ２ 相手方が正当な理由なく意思表示の通知が到達することを妨げたときは、その通知は、通常到達すべきであった時に到達したものとみなす。 ３ 意思表示は、表意者が通知を発した後に死…
% 第97条第1項: 意思表示は通知が相手方に到達した時から効力を生ずる
効力を生ずる(_相手方, _意思表示) <=
    通知の到達_f(_相手方, _意思表示).

% 第97条第2項: 相手方が正当な理由なく到達を妨げたときは通常到達すべきであった時に到達したものとみなす
通知の到達とみなす(_相手方, _意思表示) <=
    到達を正当な理由なく妨げた_f(_相手方, _意思表示).
効力を生ずる(_相手方, _意思表示) <=
    通知の到達とみなす(_相手方, _意思表示).

% ========== 第九十八条（公示による意思表示） ==========
% 条文要旨: 意思表示は、表意者が相手方を知ることができず、又はその所在を知ることができないときは、公示の方法によってすることができる。 ２ 前項の公示は、公示送達に関する民事訴訟法（平成八年法律第百九号）の規定に従い、裁判所の掲示場に掲示し、かつ、そ…
% TODO: 要件事実論に基づきルールを記述

% ========== 第九十八条の二（意思表示の受領能力） ==========
% 条文要旨: 意思表示の相手方がその意思表示を受けた時に意思能力を有しなかったとき又は未成年者若しくは成年被後見人であったときは、その意思表示をもってその相手方に対抗することができない。ただし、次に掲げる者がその意思表示を知った後は、この限りでない。 …
% 第98条の2: 相手方が受領能力を欠くときは、法定代理人等がその意思表示を知った後でなければ対抗できない
対抗不可(_相手方, _意思表示) <=
    受領能力を欠く相手方_f(_相手方, _意思表示).
exception(対抗不可(_相手方, _意思表示), 法定代理人が意思表示を知った_f(_相手方, _意思表示)).

% ========== 第九十九条（代理行為の要件及び効果） ==========
% 条文要旨: 代理人がその権限内において本人のためにすることを示してした意思表示は、本人に対して直接にその効力を生ずる。 ２ 前項の規定は、第三者が代理人に対してした意思表示について準用する。
% 代理行為の効果は本人に帰属
本人に効果帰属(_本人, _行為) <=
    代理権_f(_代理人, _本人),
    代理行為_f(_代理人, _行為),
    顕名_f(_代理人, _行為).

% ========== 第百条（本人のためにすることを示さない意思表示） ==========
% 条文要旨: 代理人が本人のためにすることを示さないでした意思表示は、自己のためにしたものとみなす。ただし、相手方が、代理人が本人のためにすることを知り、又は知ることができたときは、前条第一項の規定を準用する。
