% ========== 第百五条（法定代理人による復代理人の選任） ==========
% 条文要旨: 法定代理人は、自己の責任で復代理人を選任することができる。この場合において、やむを得ない事由があるときは、本人に対してその選任及び監督についての責任のみを負う。
