% ========== 第百七条（代理権の濫用） ==========
% 条文要旨: 代理人が自己又は第三者の利益を図る目的で代理権の範囲内の行為をした場合において、相手方がその目的を知り、又は知ることができたときは、その行為は、代理権を有しない者がした行為とみなす。
% 代理権濫用: 相手方が悪意または有過失のときは無権代理とみなす
無権代理(_行為) <=
    代理権_f(_代理人, _本人),
    代理行為_f(_代理人, _行為),
