    相手方の悪意又は有過失_f(_相手方, _行為).

% ========== 第百八条（自己契約及び双方代理等） ==========
% 条文要旨: 同一の法律行為について、相手方の代理人として、又は当事者双方の代理人としてした行為は、代理権を有しない者がした行為とみなす。ただし、債務の履行及び本人があらかじめ許諾した行為については、この限りでない。 ２ 前項本文に規定するもののほか、…
% TODO: 要件事実論に基づきルールを記述

% ========== 第百九条（代理権授与の表示による表見代理等） ==========
% 条文要旨: 第三者に対して他人に代理権を与えた旨を表示した者は、その代理権の範囲内においてその他人が第三者との間でした行為について、その責任を負う。ただし、第三者が、その他人が代理権を与えられていないことを知り、又は過失によって知らなかったときは、こ…
% 代理権授与の表示による表見代理
本人に効果帰属(_本人, _行為) <=
    代理権授与の表示_f(_本人, _第三者, _代理人),
    代理行為_f(_代理人, _行為),
    第三者の正当な信頼_f(_第三者, _行為).

% ========== 第百十条（権限外の行為の表見代理） ==========
% 条文要旨: 前条第一項本文の規定は、代理人がその権限外の行為をした場合において、第三者が代理人の権限があると信ずべき正当な理由があるときについて準用する。
% 権限外の行為の表見代理
本人に効果帰属(_本人, _行為) <=
    代理権_f(_代理人, _本人),
    権限外の代理行為_f(_代理人, _行為),
    正当な理由による信頼_f(_相手方, _行為).

% ========== 第百十一条（代理権の消滅事由） ==========
% 条文要旨: 代理権は、次に掲げる事由によって消滅する。 - 一 本人の死亡 - 二 代理人の死亡又は代理人が破産手続開始の決定若しくは後見開始の審判を受けたこと。 ２ 委任による代理権は、前項各号に掲げる事由のほか、委任の終了によって消滅する。
% 第111条第1項: 代理権は本人の死亡、代理人の死亡・破産手続開始・後見開始で消滅する（保佐開始は含まない）
代理権消滅(_代理人, _本人) <= 本人の死亡_f(_代理人, _本人).
代理権消滅(_代理人, _本人) <= 代理人の死亡_f(_代理人, _本人).
代理権消滅(_代理人, _本人) <= 代理人の破産手続開始_f(_代理人, _本人).
代理権消滅(_代理人, _本人) <= 代理人の後見開始_f(_代理人, _本人).

% 第111条第2項: 委任による代理権は委任の終了によっても消滅する
代理権消滅(_代理人, _本人) <= 委任の終了_f(_代理人, _本人).

% ========== 第百十二条（代理権消滅後の表見代理等） ==========
% 条文要旨: 他人に代理権を与えた者は、代理権の消滅後にその代理権の範囲内においてその他人が第三者との間でした行為について、代理権の消滅の事実を知らなかった第三者に対してその責任を負う。ただし、第三者が過失によってその事実を知らなかったときは、この限り…
% 代理権消滅後の表見代理
本人に効果帰属(_本人, _行為) <=
    代理権消滅(_代理人, _本人),
    代理行為_f(_代理人, _行為),
    消滅を知らなかったこと_f(_相手方, _行為).

exception(本人に効果帰属(_本人, _行為), 過失により知らなかった_f(_相手方, _行為)).

% ========== 第百十三条（無権代理） ==========
% 条文要旨: 代理権を有しない者が他人の代理人としてした契約は、本人がその追認をしなければ、本人に対してその効力を生じない。 ２ 追認又はその拒絶は、相手方に対してしなければ、その相手方に対抗することができない。ただし、相手方がその事実を知ったときは、…
% 無権代理: 本人が追認しなければ本人に対し効力を生じない
本人に効果帰属(_本人, _行為) <=
    無権代理行為_f(_代理人, _本人, _行為),
    追認_f(_本人, _行為).

% ========== 第百十四条（無権代理の相手方の催告権） ==========
% 条文要旨: 前条の場合において、相手方は、本人に対し、相当の期間を定めて、その期間内に追認をするかどうかを確答すべき旨の催告をすることができる。この場合において、本人がその期間内に確答をしないときは、追認を拒絶したものとみなす。
% TODO: 要件事実論に基づきルールを記述

% ========== 第百十五条（無権代理の相手方の取消権） ==========
% 条文要旨: 代理権を有しない者がした契約は、本人が追認をしない間は、相手方が取り消すことができる。ただし、契約の時において代理権を有しないことを相手方が知っていたときは、この限りでない。
% TODO: 要件事実論に基づきルールを記述

% ========== 第百十六条（無権代理行為の追認） ==========
% 条文要旨: 追認は、別段の意思表示がないときは、契約の時にさかのぼってその効力を生ずる。ただし、第三者の権利を害することはできない。
% TODO: 要件事実論に基づきルールを記述

% ========== 第百十七条（無権代理人の責任） ==========
% 条文要旨: 他人の代理人として契約をした者は、自己の代理権を証明したとき、又は本人の追認を得たときを除き、相手方の選択に従い、相手方に対して履行又は損害賠償の責任を負う。 ２ 前項の規定は、次に掲げる場合には、適用しない。 - 一 他人の代理人として…
% 無権代理人の責任
無権代理人の責任(_代理人, _相手方, _行為) <=
    無権代理行為_f(_代理人, _本人, _行為),
    本人の追認なし_f(_本人, _行為),
    相手方の善意無過失_f(_相手方, _行為).

% ========== 第百十八条（単独行為の無権代理） ==========
% 条文要旨: 単独行為については、その行為の時において、相手方が、代理人と称する者が代理権を有しないで行為をすることに同意し、又はその代理権を争わなかったときに限り、第百十三条から前条までの規定を準用する。代理権を有しない者に対しその同意を得て単独行為…
% TODO: 要件事実論に基づきルールを記述

% ========== 第百十九条（無効な行為の追認） ==========
% 条文要旨: 無効な行為は、追認によっても、その効力を生じない。ただし、当事者がその行為の無効であることを知って追認をしたときは、新たな行為をしたものとみなす。
% TODO: 要件事実論に基づきルールを記述

% ========== 第百二十条（取消権者） ==========
% 条文要旨: 行為能力の制限によって取り消すことができる行為は、制限行為能力者（他の制限行為能力者の法定代理人としてした行為にあっては、当該他の制限行為能力者を含む。）又はその代理人、承継人若しくは同意をすることができる者に限り、取り消すことができる。…
% 取消権者
取消権者(_者, _行為) <=
    取消可能(_行為),
    制限行為能力者本人又は代理人等_f(_者, _行為).

取消権者(_者, _行為) <=
    取消可能(_行為),
    瑕疵ある意思表示の表意者_f(_者, _行為).

% ========== 第百二十一条（取消しの効果） ==========
% 条文要旨: 取り消された行為は、初めから無効であったものとみなす。
% 取消しの効果: 初めから無効であったとみなす
初めから無効(_行為) <=
    取消しの意思表示_f(_取消権者, _行為),
    取消権者(_取消権者, _行為).

% ========== 第百二十一条の二（原状回復の義務） ==========
% 条文要旨: 無効な行為に基づく債務の履行として給付を受けた者は、相手方を原状に復させる義務を負う。 ２ 前項の規定にかかわらず、無効な無償行為に基づく債務の履行として給付を受けた者は、給付を受けた当時その行為が無効であること（給付を受けた後に前条の規…
% 原状回復義務
原状回復義務(_当事者, _行為) <=
    初めから無効(_行為),
    給付を受けた_f(_当事者, _行為).

% ========== 第百二十二条（取り消すことができる行為の追認） ==========
% 条文要旨: 取り消すことができる行為は、第百二十条に規定する者が追認したときは、以後、取り消すことができない。
% 第122条: 取り消すことができる行為は、追認したときは以後取り消すことができない
追認済み(_行為) <= 取消権の追認_f(_行為).
exception(取消可能(_行為), 追認済み(_行為)).

% ========== 第百二十三条（取消し及び追認の方法） ==========
% 条文要旨: 取り消すことができる行為の相手方が確定している場合には、その取消し又は追認は、相手方に対する意思表示によってする。
% TODO: 要件事実論に基づきルールを記述

% ========== 第百二十四条（追認の要件） ==========
% 条文要旨: 取り消すことができる行為の追認は、取消しの原因となっていた状況が消滅し、かつ、取消権を有することを知った後にしなければ、その効力を生じない。 ２ 次に掲げる場合には、前項の追認は、取消しの原因となっていた状況が消滅した後にすることを要しな…
% 第124条第1項: 追認は取消しの原因となっていた状況が消滅し、かつ取消権を知った後でなければ効力を生じない
% （第2項の例外は未実装）
