% ========== 第百九十二条（即時取得） ==========
% 条文要旨: 取引行為によって、平穏に、かつ、公然と動産の占有を始めた者は、善意であり、かつ、過失がないときは、即時にその動産について行使する権利を取得する。
% 即時取得
所有権取得(_占有者, _動産) <=
    動産の取引行為による占有開始_f(_占有者, _動産),
    平穏かつ公然_f(_占有者, _動産),
    善意無過失_f(_占有者, _動産).

% ========== 第百九十三条（盗品又は遺失物の回復） ==========
% 条文要旨: 前条の場合において、占有物が盗品又は遺失物であるときは、被害者又は遺失者は、盗難又は遺失の時から二年間、占有者に対してその物の回復を請求することができる。
% 盗品または遺失物の回復
回復請求できる(_被害者, _占有者, _動産) <=
    即時取得(_占有者, _動産),
    盗品又は遺失物_f(_動産),
    二年以内の請求_f(_被害者, _動産).

