% 債務不履行による損害賠償
損害賠償請求(_債権者, _債務者, _損害) <=
    債務_f(_債務者, _債権者),
    債務不履行_f(_債務者),
    損害の発生_f(_債権者, _損害),
    因果関係_f(_債務者, _損害).

exception(損害賠償請求(_債権者, _債務者, _損害), 債務者の免責事由_f(_債務者)).

% ========== 第四百十六条（損害賠償の範囲） ==========
% 条文要旨: 債務の不履行に対する損害賠償の請求は、これによって通常生ずべき損害の賠償をさせることをその目的とする。 ２ 特別の事情によって生じた損害であっても、当事者がその事情を予見すべきであったときは、債権者は、その賠償を請求することができる。
% 損害賠償の範囲（通常損害）
通常損害として賠償される(_損害) <=
    損害賠償請求(_債権者, _債務者, _損害),
    通常生ずべき損害_f(_損害).

% 特別事情による損害
特別損害として賠償される(_損害) <=
    損害賠償請求(_債権者, _債務者, _損害),
    特別事情による損害_f(_損害),
    予見可能性_f(_債務者, _損害).

