% ========== 第六百十二条（賃借権の譲渡及び転貸の制限） ==========
% 条文要旨: 賃借人は、賃貸人の承諾を得なければ、その賃借権を譲り渡し、又は賃借物を転貸することができない。 ２ 賃借人が前項の規定に違反して第三者に賃借物の使用又は収益をさせたときは、賃貸人は、契約の解除をすることができる。
% 賃借権の譲渡・転貸に賃貸人の承諾が必要。違反は解除事由となりうる
賃貸人の解除権(_賃貸人, _契約) <=
    不動産賃貸借契約_f(_契約),
    賃借権譲渡又は転貸_f(_賃借人, _契約),
    賃貸人の承諾なし_f(_賃貸人, _契約).

% 信頼関係不破壊の法理（例外）
exception(賃貸人の解除権(_賃貸人, _契約), 信頼関係破壊なし_f(_契約)).

