% 不法行為による損害賠償
損害賠償義務(_加害者, _被害者, _損害) <=
    故意又は過失_f(_加害者),
    権利侵害_f(_加害者, _被害者),
    損害の発生_f(_被害者, _損害),
    因果関係_f(_加害者, _損害).

