% 財産以外の損害（慰謝料）も賠償範囲に含まれうる
損害賠償義務(_加害者, _被害者, _精神的損害) <=
    損害賠償義務(_加害者, _被害者, _財産的損害),
    精神的損害の発生_f(_被害者, _精神的損害).

